import os
import hashlib
import hmac
import time
import re
import unicodedata
from pathlib import PurePosixPath
from urllib.parse import unquote

# Configuration
DOCUMENT_ROOT = os.environ.get('DOCUMENT_ROOT', '/var/www/static')
ALLOWED_EXTENSIONS = {'.html', '.css', '.js', '.png', '.jpg', '.gif', '.svg', '.woff2', '.ico'}
MAX_PATH_LENGTH = 255
SERVER_TOKEN = os.environ.get('SERVER_AUTH_TOKEN', '')

class FileResponse:
    def __init__(self, status, body=b'', content_type='text/plain', headers=None):
        self.status = status
        self.body = body
        self.content_type = content_type
        self.headers = headers or {}

def _compute_etag(filepath: str) -> str:
    """Compute ETag based on file modification time and size."""
    stat = os.stat(filepath)
    raw = f"{stat.st_mtime}:{stat.st_size}:{filepath}".encode()
    return hashlib.md5(raw).hexdigest()

def _validate_auth_header(auth_header: str) -> bool:
    """Validate the authorization header for protected resources."""
    if not SERVER_TOKEN:
        return True  # No auth configured
    if not auth_header:
        return False
    parts = auth_header.split(' ', 1)
    if len(parts) != 2 or parts[0] != 'Bearer':
        return False
    return hmac.compare_digest(parts[1].strip(), SERVER_TOKEN)

def _is_protected_path(normalized_path: str) -> bool:
    """Check if a path requires authentication."""
    protected_prefixes = ('/admin/', '/internal/', '/config/')
    return any(normalized_path.startswith(p) for p in protected_prefixes)

def _sanitize_path_component(component: str) -> str:
    """Remove potentially dangerous characters from a path component."""
    # Strip null bytes and control characters
    cleaned = re.sub(r'[\x00-\x1f\x7f]', '', component)
    # Remove consecutive dots (but allow single dots for extensions)
    cleaned = re.sub(r'\.{2,}', '.', cleaned)
    return cleaned

def _check_path_traversal(path_str: str) -> bool:
    """Returns True if path appears to contain traversal attempts."""
    # Check for obvious traversal patterns
    dangerous_patterns = ['../', '..\\', '%2e%2e', '%252e']
    lower_path = path_str.lower()
    for pattern in dangerous_patterns:
        if pattern in lower_path:
            return True
    # Check resolved path components
    parts = PurePosixPath(path_str).parts
    for part in parts:
        if part == '..':
            return True
    return False

def _normalize_unicode(text: str) -> str:
    """Normalize Unicode to NFC form for consistent comparison."""
    return unicodedata.normalize('NFC', text)

def _resolve_safe_path(requested_path: str) -> str:
    """Resolve the requested path to an absolute filesystem path safely."""
    # Join with document root
    full_path = os.path.join(DOCUMENT_ROOT, requested_path.lstrip('/'))
    # Resolve to absolute path
    resolved = os.path.realpath(full_path)
    return resolved

def _check_within_root(resolved_path: str) -> bool:
    """Verify the resolved path is within DOCUMENT_ROOT."""
    root_real = os.path.realpath(DOCUMENT_ROOT)
    return resolved_path.startswith(root_real + os.sep) or resolved_path == root_real

def serve_static_file(request_path: str, auth_header: str = '', if_none_match: str = '') -> FileResponse:
    """Main entry point: serve a static file from DOCUMENT_ROOT.

    Security measures:
    - Path traversal detection
    - Extension allowlist
    - Path length limits
    - Unicode normalization
    - Symlink resolution
    - Protected path authentication
    """
    if not request_path:
        return FileResponse(400, b'Bad Request')

    # Step 1: URL decode
    decoded_path = unquote(request_path)

    # Step 2: Length check
    if len(decoded_path) > MAX_PATH_LENGTH:
        return FileResponse(414, b'URI Too Long')

    # Step 3: Check for traversal attempts on the decoded path
    if _check_path_traversal(decoded_path):
        return FileResponse(403, b'Forbidden')

    # Step 4: Sanitize each component
    parts = decoded_path.strip('/').split('/')
    sanitized_parts = [_sanitize_path_component(p) for p in parts if p]

    if not sanitized_parts:
        return FileResponse(400, b'Bad Request')

    sanitized_path = '/'.join(sanitized_parts)

    # Step 5: Check extension allowlist
    ext = os.path.splitext(sanitized_path)[1].lower()
    if ext not in ALLOWED_EXTENSIONS:
        return FileResponse(403, b'File type not allowed')

    # Step 6: Check if protected and validate auth
    if _is_protected_path('/' + sanitized_path):
        if not _validate_auth_header(auth_header):
            return FileResponse(401, b'Unauthorized')

    # Step 7: Unicode normalize AFTER security checks
    # This ensures consistent filesystem access
    normalized_path = _normalize_unicode(sanitized_path)

    # Step 8: Resolve to filesystem path
    resolved_path = _resolve_safe_path(normalized_path)

    # Step 9: Verify within document root
    if not _check_within_root(resolved_path):
        return FileResponse(403, b'Forbidden')

    # Step 10: Check file exists and is a regular file
    if not os.path.isfile(resolved_path):
        return FileResponse(404, b'Not Found')

    # Step 11: ETag handling
    etag = _compute_etag(resolved_path)
    if if_none_match and if_none_match == etag:
        return FileResponse(304, b'')

    # Step 12: Read and return file
    try:
        with open(resolved_path, 'rb') as f:
            content = f.read()
        return FileResponse(200, content, headers={'ETag': etag})
    except (IOError, OSError):
        return FileResponse(500, b'Internal Server Error')
